import random

def get_user_choice():
    """Get user's choice as 'rock', 'paper', or 'scissors'."""
    while True:
        user_choice = input("Enter 'rock', 'paper', or 'scissors': ").lower()
        if user_choice in ['rock', 'paper', 'scissors']:
            return user_choice
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def play_game():
    """Simulate a single game of Rock-Paper-Scissors."""
    user_choice = get_user_choice()
    computer_choice = random.choice(['rock', 'paper', 'scissors'])

    if user_choice == computer_choice:
        print(f"It's a tie! You chose {user_choice} and the computer chose {computer_choice}.")
    elif (user_choice == 'rock' and computer_choice == 'scissors') or \
         (user_choice == 'paper' and computer_choice == 'rock') or \
         (user_choice == 'scissors' and computer_choice == 'paper'):
        print(f"You win! You chose {user_choice} and the computer chose {computer_choice}.")
    else:
        print(f"You lose! You chose {user_choice} and the computer chose {computer_choice}.")

while True:
    play_game()
    user_quit = input("Do you want to play again? (yes/no): ").lower()
    if user_quit != 'yes':
        break
```

This program defines two functions: `get_user_choice()` to get the user's choice and `play_game()` to simulate a single game of Rock-Paper-Scissors. The `while` loop continues to run until the user chooses to quit.
